package adr

import (
	"bytes"
	"fmt"
	"os"
	"slices"
	"strings"
	"testing"

	"github.com/ma-chisuke/kortopi/tools/internal/i18n"
)

func TestWriteIndex(t *testing.T) {
	dir := newRepo(t)
	en := readFile(t, dir, indexEN)
	wantEN := "# Architecture decision records\n" +
		"\n" +
		"<!-- Generated by make gen. Do not edit. -->\n" +
		"\n" +
		fmt.Sprintf(indexEnglish.intro, "[ADR-0001](ADR-0001-record-decisions.md)") + "\n" +
		"\n" +
		"| ID | Decision | Status | Date |\n" +
		"|---|---|---|---|\n" +
		"| [ADR-0001](ADR-0001-record-decisions.md) | Record decisions | accepted | 2026-11-17 |\n" +
		"| [ADR-0002](ADR-0002-use-sqlite.md) | Use SQLite | superseded by [ADR-0003](ADR-0003-use-postgresql.md) | 2026-11-17 |\n" +
		"| [ADR-0003](ADR-0003-use-postgresql.md) | Use PostgreSQL | accepted | 2026-11-17 |\n"
	if en != wantEN {
		t.Errorf("README.md:\n%s\nwant:\n%s", en, wantEN)
	}

	ja := readFile(t, dir, indexJA)
	wantJA := "# アーキテクチャの決定の記録\n" +
		"\n" +
		"<!-- Generated by make gen. Do not edit. -->\n" +
		"\n" +
		fmt.Sprintf(indexJapanese.intro, "[ADR-0001](ADR-0001-record-decisions.ja.md)") + "\n" +
		"\n" +
		"| ID | 決定 | 状態 | 日付 |\n" +
		"|---|---|---|---|\n" +
		"| [ADR-0001](ADR-0001-record-decisions.ja.md) | 決定を記録する | accepted | 2026-11-17 |\n" +
		"| [ADR-0002](ADR-0002-use-sqlite.ja.md) | SQLite を使う | 次の記録が置き換えた：[ADR-0003](ADR-0003-use-postgresql.ja.md) | 2026-11-17 |\n" +
		"| [ADR-0003](ADR-0003-use-postgresql.ja.md) | PostgreSQL を使う | accepted | 2026-11-17 |\n" +
		"\n" +
		i18n.Marker("README.md", []byte(en)) + "\n"
	if ja != wantJA {
		t.Errorf("README.ja.md:\n%s\nwant:\n%s", ja, wantJA)
	}

	// The marker makes the pair pass the translation check.
	findings, err := i18n.Check(os.DirFS(dir), []string{indexJA, indexEN})
	if err != nil || len(findings) > 0 {
		t.Errorf("i18n.Check() = %v, %v; want no findings", findings, err)
	}

	// A second run changes nothing.
	var out bytes.Buffer
	if err := WriteIndex(openRoot(t, dir), &out); err != nil {
		t.Fatal(err)
	}
	if out.Len() > 0 {
		t.Errorf("a second WriteIndex() reported %q, want nothing", out.String())
	}
}

func TestWriteIndexCases(t *testing.T) {
	tests := []struct {
		name    string
		files   map[string]string
		want    []string // lines of README.md
		wantJA  []string // lines of README.ja.md
		without []string // text of neither
	}{
		{
			name:    "no records",
			files:   map[string]string{"docs/adr/.keep": ""},
			want:    []string{"None yet.", fmt.Sprintf(indexEnglish.intro, "ADR-0001")},
			wantJA:  []string{"まだない。", fmt.Sprintf(indexJapanese.intro, "ADR-0001")},
			without: []string{"| ID |", "|---|"},
		},
		{
			name:    "no directory of records",
			want:    []string{"None yet."},
			wantJA:  []string{"まだない。"},
			without: []string{"| ID |", "|---|"},
		},
		{
			name: "a proposed record does not supersede",
			files: map[string]string{
				adr1EN: recordText(enRecord, "ADR-0001", "Record decisions", ""),
				"docs/adr/ADR-0002-replace.md": strings.Replace(recordText(enRecord, "ADR-0002", "Replace", "supersedes: [ADR-0001]"),
					"status: accepted", "status: proposed", 1),
			},
			without: []string{"superseded by", "次の記録が置き換えた"},
		},
		{
			name: "two records supersede one, and a missing translation falls back to English",
			files: map[string]string{
				adr1EN:                   recordText(enRecord, "ADR-0001", "Record decisions", ""),
				"docs/adr/ADR-0002-a.md": recordText(enRecord, "ADR-0002", "First | second", "supersedes: [ADR-0001]"),
				"docs/adr/ADR-0003-b.md": recordText(enRecord, "ADR-0003", "B", "supersedes: [ADR-0001]"),
			},
			want: []string{
				"| [ADR-0001](ADR-0001-record-decisions.md) | Record decisions | superseded by [ADR-0002](ADR-0002-a.md), [ADR-0003](ADR-0003-b.md) | 2026-11-17 |",
				"| [ADR-0002](ADR-0002-a.md) | First \\| second | accepted | 2026-11-17 |",
			},
			wantJA: []string{
				fmt.Sprintf(indexJapanese.intro, "[ADR-0001](ADR-0001-record-decisions.md)"),
				"| [ADR-0001](ADR-0001-record-decisions.md) | Record decisions | 次の記録が置き換えた：[ADR-0002](ADR-0002-a.md)、[ADR-0003](ADR-0003-b.md) | 2026-11-17 |",
				"| [ADR-0002](ADR-0002-a.md) | First \\| second | accepted | 2026-11-17 |",
			},
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			dir := t.TempDir()
			for name, content := range tt.files {
				writeFile(t, dir, name, content)
			}
			writeIndex(t, dir)
			en := strings.Split(readFile(t, dir, indexEN), "\n")
			ja := strings.Split(readFile(t, dir, indexJA), "\n")
			for _, line := range tt.want {
				if !slices.Contains(en, line) {
					t.Errorf("README.md lacks the line %q:\n%s", line, strings.Join(en, "\n"))
				}
			}
			for _, line := range tt.wantJA {
				if !slices.Contains(ja, line) {
					t.Errorf("README.ja.md lacks the line %q:\n%s", line, strings.Join(ja, "\n"))
				}
			}
			for _, text := range tt.without {
				for name, lines := range map[string][]string{"README.md": en, "README.ja.md": ja} {
					if joined := strings.Join(lines, "\n"); strings.Contains(joined, text) {
						t.Errorf("%s contains %q:\n%s", name, text, joined)
					}
				}
			}
		})
	}
}
